package hosts

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

const (
	StatusOn  = "on"
	StatusOff = "off"

	DefaultProfile = "default"

	profileMarkerOn  = "profile.on"
	profileMarkerOff = "profile.off"
	profileMarkerOnOld  = "profile:on"
	profileMarkerOffOld = "profile:off"

	endMarker   = "# end"
	hostctlComment = "# hostctl"

	banner1 = "##################################################################"
	banner2 = "# Content under this line is handled by hostctl. DO NOT EDIT."
)

// Row represents a single row in the hosts file
type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

// Profile represents a hostctl-managed profile
type Profile struct {
	Name   string
	Status string
	Rows   []*Row
}

// HostsFile represents the entire hosts file
type HostsFile struct {
	Path           string
	DefaultRows    []*Row      // raw lines in default section
	DefaultLines   []string    // raw text lines of the default section
	Profiles       []*Profile  // ordered profiles
	ProfileMap     map[string]*Profile
	HasHostctlComment bool // whether # hostctl marker was present
}

// Load reads and parses a hosts file
func Load(path string) (*HostsFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	hf := &HostsFile{
		Path:       path,
		ProfileMap: make(map[string]*Profile),
	}

	scanner := bufio.NewScanner(f)

	// Parse state
	inHostctl := false  // We've passed the hostctl section marker
	currentProfile := (*Profile)(nil)
	var defaultLines []string

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if trimmed == hostctlComment {
			hf.HasHostctlComment = true
			defaultLines = append(defaultLines, line)
			inHostctl = true
			continue
		}

		if !inHostctl {
			// In the default section
			defaultLines = append(defaultLines, line)
			continue
		}

		// In hostctl section
		if trimmed == banner1 || trimmed == banner2 {
			// Skip banner lines
			continue
		}

		if trimmed == "" {
			// Empty line - skip in hostctl section
			continue
		}

		// Check for profile marker
		if strings.HasPrefix(trimmed, "# profile.on ") || strings.HasPrefix(trimmed, "# profile:on ") {
			profileName := ""
			if strings.HasPrefix(trimmed, "# profile.on ") {
				profileName = strings.TrimPrefix(trimmed, "# profile.on ")
			} else {
				profileName = strings.TrimPrefix(trimmed, "# profile:on ")
			}
			profileName = strings.TrimSpace(profileName)
			p := &Profile{Name: profileName, Status: StatusOn}
			hf.Profiles = append(hf.Profiles, p)
			hf.ProfileMap[profileName] = p
			currentProfile = p
			continue
		}

		if strings.HasPrefix(trimmed, "# profile.off ") || strings.HasPrefix(trimmed, "# profile:off ") {
			profileName := ""
			if strings.HasPrefix(trimmed, "# profile.off ") {
				profileName = strings.TrimPrefix(trimmed, "# profile.off ")
			} else {
				profileName = strings.TrimPrefix(trimmed, "# profile:off ")
			}
			profileName = strings.TrimSpace(profileName)
			p := &Profile{Name: profileName, Status: StatusOff}
			hf.Profiles = append(hf.Profiles, p)
			hf.ProfileMap[profileName] = p
			currentProfile = p
			continue
		}

		if trimmed == endMarker {
			currentProfile = nil
			continue
		}

		// Parse entry line
		if currentProfile != nil {
			isComment := false
			entryLine := trimmed
			if strings.HasPrefix(entryLine, "# ") {
				isComment = true
				entryLine = strings.TrimPrefix(entryLine, "# ")
			}

			parts := strings.Fields(entryLine)
			if len(parts) >= 2 {
				ip := parts[0]
				for _, host := range parts[1:] {
					row := &Row{
						Profile: currentProfile.Name,
						Status:  currentProfile.Status,
						IP:      ip,
						Host:    host,
					}
					_ = isComment // Status already set by profile
					currentProfile.Rows = append(currentProfile.Rows, row)
				}
			}
		}
	}

	hf.DefaultLines = defaultLines

	// Parse default rows from default lines
	for _, dl := range defaultLines {
		trimmed := strings.TrimSpace(dl)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		parts := strings.Fields(trimmed)
		if len(parts) >= 2 {
			ip := parts[0]
			// Only first hostname
			row := &Row{
				Profile: DefaultProfile,
				Status:  StatusOn,
				IP:      ip,
				Host:    parts[1],
			}
			hf.DefaultRows = append(hf.DefaultRows, row)
		}
	}

	return hf, scanner.Err()
}

// GetAllRows returns all rows (default + profiles)
func (hf *HostsFile) GetAllRows(profileFilter []string) []*Row {
	var rows []*Row

	filterMap := make(map[string]bool)
	hasFilter := len(profileFilter) > 0
	for _, p := range profileFilter {
		filterMap[p] = true
	}

	if !hasFilter || filterMap[DefaultProfile] {
		rows = append(rows, hf.DefaultRows...)
	}

	for _, p := range hf.Profiles {
		if hasFilter && !filterMap[p.Name] {
			continue
		}
		rows = append(rows, p.Rows...)
	}

	return rows
}

// GetProfile returns a profile by name
func (hf *HostsFile) GetProfile(name string) *Profile {
	return hf.ProfileMap[name]
}

// GetProfileNames returns all non-default profile names
func (hf *HostsFile) GetProfileNames() []string {
	var names []string
	for _, p := range hf.Profiles {
		names = append(names, p.Name)
	}
	return names
}

// Save writes the hosts file back to disk
func (hf *HostsFile) Save() error {
	f, err := os.Create(hf.Path)
	if err != nil {
		return err
	}
	defer f.Close()

	w := bufio.NewWriter(f)

	// Write default section
	// First, write the default lines (excluding the "# hostctl" comment since we add it back)
	hasHostctlInDefault := false
	var defaultLinesFiltered []string
	for _, dl := range hf.DefaultLines {
		trimmed := strings.TrimSpace(dl)
		if trimmed == hostctlComment {
			hasHostctlInDefault = true
			continue // we'll add it back after default section
		}
		defaultLinesFiltered = append(defaultLinesFiltered, dl)
	}

	// Write the default rows (only IP + first hostname)
	// Actually, we need to write the original default lines but:
	// 1. Skip empty lines at end
	// 2. For ip lines, only keep first hostname
	// 3. Skip comments
	for _, dl := range defaultLinesFiltered {
		trimmed := strings.TrimSpace(dl)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		parts := strings.Fields(trimmed)
		if len(parts) >= 2 {
			fmt.Fprintf(w, "%s %s\n", parts[0], parts[1])
		}
	}

	// Write blank line + hostctl comment if it was there
	fmt.Fprintln(w)
	if hasHostctlInDefault || hf.HasHostctlComment {
		fmt.Fprintln(w, hostctlComment)
		fmt.Fprintln(w)
	}

	// Write banner
	fmt.Fprintln(w, banner1)
	fmt.Fprintln(w, banner2)
	fmt.Fprintln(w, banner1)

	// Write profiles
	for _, p := range hf.Profiles {
		fmt.Fprintln(w)
		if p.Status == StatusOn {
			fmt.Fprintf(w, "# profile.on %s\n", p.Name)
		} else {
			fmt.Fprintf(w, "# profile.off %s\n", p.Name)
		}

		for _, row := range p.Rows {
			if p.Status == StatusOn {
				fmt.Fprintf(w, "%s %s\n", row.IP, row.Host)
			} else {
				fmt.Fprintf(w, "# %s %s\n", row.IP, row.Host)
			}
		}

		fmt.Fprintln(w, endMarker)
	}

	return w.Flush()
}

// AddProfile adds or updates a profile
func (hf *HostsFile) AddProfile(name string, rows []*Row) {
	existing := hf.ProfileMap[name]
	if existing == nil {
		p := &Profile{
			Name:   name,
			Status: StatusOn,
			Rows:   rows,
		}
		hf.Profiles = append(hf.Profiles, p)
		hf.ProfileMap[name] = p
	} else {
		existing.Rows = append(existing.Rows, rows...)
	}
}

// ReplaceProfile replaces a profile's content or creates new
func (hf *HostsFile) ReplaceProfile(name string, rows []*Row) {
	existing := hf.ProfileMap[name]
	if existing == nil {
		p := &Profile{
			Name:   name,
			Status: StatusOn,
			Rows:   rows,
		}
		hf.Profiles = append(hf.Profiles, p)
		hf.ProfileMap[name] = p
	} else {
		existing.Rows = rows
		existing.Status = StatusOn
	}
}

// RemoveProfile removes a profile
func (hf *HostsFile) RemoveProfile(name string) bool {
	_, exists := hf.ProfileMap[name]
	if !exists {
		return false
	}
	delete(hf.ProfileMap, name)

	var newProfiles []*Profile
	for _, p := range hf.Profiles {
		if p.Name != name {
			newProfiles = append(newProfiles, p)
		}
	}
	hf.Profiles = newProfiles
	return true
}

// RemoveDomains removes specific domains from a profile
func (hf *HostsFile) RemoveDomains(profileName string, domains []string) bool {
	p := hf.ProfileMap[profileName]
	if p == nil {
		return false
	}

	domainMap := make(map[string]bool)
	for _, d := range domains {
		domainMap[d] = true
	}

	var newRows []*Row
	for _, row := range p.Rows {
		if !domainMap[row.Host] {
			newRows = append(newRows, row)
		}
	}
	p.Rows = newRows
	return true
}

// EnableProfile enables a profile
func (hf *HostsFile) EnableProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	p.Status = StatusOn
	for _, row := range p.Rows {
		row.Status = StatusOn
	}
	return true
}

// DisableProfile disables a profile
func (hf *HostsFile) DisableProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	p.Status = StatusOff
	for _, row := range p.Rows {
		row.Status = StatusOff
	}
	return true
}

// ToggleProfile toggles a profile status
func (hf *HostsFile) ToggleProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	if p.Status == StatusOn {
		return hf.DisableProfile(name)
	}
	return hf.EnableProfile(name)
}

// ParseRows parses lines from a reader into rows
func ParseRows(lines []string) []*Row {
	var rows []*Row
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		parts := strings.Fields(trimmed)
		if len(parts) >= 2 {
			ip := parts[0]
			for _, host := range parts[1:] {
				rows = append(rows, &Row{
					IP:     ip,
					Host:   host,
					Status: StatusOn,
				})
			}
		}
	}
	return rows
}
