		existing.Status = StatusOn
	}
}

// RemoveProfile removes a profile
func (hf *HostsFile) RemoveProfile(name string) bool {
	_, exists := hf.ProfileMap[name]
	if !exists {
		return false
	}
	delete(hf.ProfileMap, name)

	var newProfiles []*Profile
	for _, p := range hf.Profiles {
		if p.Name != name {
			newProfiles = append(newProfiles, p)
		}
	}
	hf.Profiles = newProfiles
	return true
}

// RemoveDomains removes specific domains from a profile
func (hf *HostsFile) RemoveDomains(profileName string, domains []string) bool {
	p := hf.ProfileMap[profileName]
	if p == nil {
		return false
	}

	domainMap := make(map[string]bool)
	for _, d := range domains {
		domainMap[d] = true
	}

