}

// ToggleProfile toggles a profile status
func (hf *HostsFile) ToggleProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	if p.Status == StatusOn {
		return hf.DisableProfile(name)
	}
	return hf.EnableProfile(name)
}

// ParseRows parses lines from a reader into rows
func ParseRows(lines []string) []*Row {
	var rows []*Row
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
