package renderer

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

// OutputType represents the output format type
type OutputType string

const (
	OutputTable    OutputType = "table"
	OutputRaw      OutputType = "raw"
	OutputMarkdown OutputType = "markdown"
	OutputJSON     OutputType = "json"
)

// Column represents a table column
type Column struct {
	Name  string
	Key   string
}

// Row represents a table row
type Row map[string]string

// Renderer renders table data
type Renderer struct {
	Output   OutputType
	Columns  []Column
	Writer   io.Writer
	NoColor  bool
	Quiet    bool
	Groups   []Group
}

// Group is a group of rows (for profile-based grouping)
type Group struct {
	Rows    []Row
	Profile string
	Status  string
}

// New creates a new renderer
func New(w io.Writer, output OutputType) *Renderer {
	return &Renderer{
		Output: output,
		Writer: w,
	}
}

// SetColumns sets the visible columns
func (r *Renderer) SetColumns(cols []Column) {
	r.Columns = cols
}

// Render renders all groups
func (r *Renderer) Render(groups []Group, cols []Column) {
	if r.Output == OutputJSON {
		r.renderJSON(groups, cols)
		return
	}

	if r.Output == OutputRaw {
		r.renderRaw(groups, cols)
		return
	}

	if r.Output == OutputMarkdown {
		r.renderMarkdown(groups, cols)
		return
	}

	// Default: table
	r.renderTable(groups, cols)
}

func (r *Renderer) renderJSON(groups []Group, cols []Column) {
	type jsonRow struct {
		Profile string `json:"Profile"`
		Status  string `json:"Status"`
		IP      string `json:"IP"`
		Host    string `json:"Host"`
	}

	var rows []jsonRow
	for _, g := range groups {
		for _, row := range g.Rows {
			jr := jsonRow{
				Profile: getField(row, "profile"),
