package renderer

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

// OutputType represents the output format type
type OutputType string

const (
	OutputTable    OutputType = "table"
	OutputRaw      OutputType = "raw"
	OutputMarkdown OutputType = "markdown"
	OutputJSON     OutputType = "json"
)

// Column represents a table column
type Column struct {
	Name  string
	Key   string
}

// Row represents a table row
type Row map[string]string

// Renderer renders table data
type Renderer struct {
	Output   OutputType
	Columns  []Column
	Writer   io.Writer
	NoColor  bool
	Quiet    bool
	Groups   []Group
}

// Group is a group of rows (for profile-based grouping)
type Group struct {
	Rows    []Row
	Profile string
	Status  string
}

// New creates a new renderer
func New(w io.Writer, output OutputType) *Renderer {
	return &Renderer{
		Output: output,
		Writer: w,
	}
}

// SetColumns sets the visible columns
func (r *Renderer) SetColumns(cols []Column) {
	r.Columns = cols
}

// Render renders all groups
func (r *Renderer) Render(groups []Group, cols []Column) {
	if r.Output == OutputJSON {
		r.renderJSON(groups, cols)
		return
	}

	if r.Output == OutputRaw {
		r.renderRaw(groups, cols)
		return
	}

	if r.Output == OutputMarkdown {
		r.renderMarkdown(groups, cols)
		return
	}

	// Default: table
	r.renderTable(groups, cols)
}

func (r *Renderer) renderJSON(groups []Group, cols []Column) {
	type jsonRow struct {
		Profile string `json:"Profile"`
		Status  string `json:"Status"`
		IP      string `json:"IP"`
		Host    string `json:"Host"`
	}

	var rows []jsonRow
	for _, g := range groups {
		for _, row := range g.Rows {
			jr := jsonRow{
				Profile: getField(row, "profile"),
				Status:  getField(row, "status"),
				IP:      getField(row, "ip"),
				Host:    getField(row, "host"),
			}
			rows = append(rows, jr)
		}
	}

	data, _ := json.Marshal(rows)
	fmt.Fprintf(r.Writer, "%s\n", data)
}

func getField(row Row, key string) string {
	// Try exact match first
	for k, v := range row {
		if strings.ToLower(k) == strings.ToLower(key) {
			return v
		}
	}
	return ""
}

func (r *Renderer) getColValue(row Row, col Column) string {
	// Try the column key
	if v, ok := row[col.Key]; ok {
		return v
	}
	// Try lowercase key
	for k, v := range row {
		if strings.ToLower(k) == strings.ToLower(col.Key) {
			return v
		}
	}
	return ""
}

func (r *Renderer) renderRaw(groups []Group, cols []Column) {
	// Calculate column widths
	widths := make([]int, len(cols))
	for i, col := range cols {
		widths[i] = utf8.RuneCountInString(col.Name)
	}

	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
				val := r.getColValue(row, col)
				if l := utf8.RuneCountInString(val); l > widths[i] {
					widths[i] = l
				}
			}
		}
	}

	// Write header
	for i, col := range cols {
		fmt.Fprintf(r.Writer, "%-*s", widths[i], col.Name)
		if i < len(cols)-1 {
			fmt.Fprint(r.Writer, "\t")
		}
	}
	fmt.Fprintln(r.Writer, " ")

	// Write rows
	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
				val := r.getColValue(row, col)
				fmt.Fprintf(r.Writer, "%-*s", widths[i], val)
				fmt.Fprint(r.Writer, "\t")
			}
			fmt.Fprintln(r.Writer)
		}
	}
}

func (r *Renderer) renderMarkdown(groups []Group, cols []Column) {
	// Calculate column widths
	widths := make([]int, len(cols))
	for i, col := range cols {
		widths[i] = utf8.RuneCountInString(col.Name)
	}

	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
				val := r.getColValue(row, col)
				if l := utf8.RuneCountInString(val); l > widths[i] {
					widths[i] = l
				}
			}
		}
	}

	// Write header
	fmt.Fprint(r.Writer, "|")
	for i, col := range cols {
		fmt.Fprintf(r.Writer, " %-*s |", widths[i], col.Name)
		_ = i
	}
	fmt.Fprintln(r.Writer)

	// Write separator
	fmt.Fprint(r.Writer, "|")
	for i, col := range cols {
		_ = col
		fmt.Fprintf(r.Writer, "%s|", strings.Repeat("-", widths[i]+2))
		_ = i
	}
	fmt.Fprintln(r.Writer)

	// Write rows
	lastProfile := ""
	for gi, g := range groups {
		// Add separator between groups (except for the first group, markdown doesn't have +-- separators)
		if gi > 0 && g.Rows != nil && len(g.Rows) > 0 && lastProfile != "" {
			// In markdown format, there's a separator row between groups
			fmt.Fprint(r.Writer, "|")
			for i, col := range cols {
				_ = col
				fmt.Fprintf(r.Writer, "%s|", strings.Repeat("-", widths[i]+2))
				_ = i
			}
			fmt.Fprintln(r.Writer)
		}

		for _, row := range g.Rows {
			fmt.Fprint(r.Writer, "|")
			for _, col := range cols {
				val := r.getColValue(row, col)
				fmt.Fprintf(r.Writer, " %-*s |", widths[i_col(cols, col)], val)
			}
			fmt.Fprintln(r.Writer)
		}

		if len(g.Rows) > 0 {
			lastProfile = g.Profile
		}
	}
}

func i_col(cols []Column, col Column) int {
	for i, c := range cols {
		if c.Key == col.Key {
			return i
		}
	}
	return 0
}

// calculateWidths returns the max width for each column
func calculateWidths(groups []Group, cols []Column, getVal func(Row, Column) string) []int {
	widths := make([]int, len(cols))
	for i, col := range cols {
		widths[i] = utf8.RuneCountInString(col.Name)
	}

	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
				val := getVal(row, col)
				if l := utf8.RuneCountInString(val); l > widths[i] {
					widths[i] = l
				}
			}
		}
	}

	return widths
}

func (r *Renderer) renderTable(groups []Group, cols []Column) {
	widths := calculateWidths(groups, cols, r.getColValue)

	separator := buildSeparator(widths)

	// Write top border
	fmt.Fprintln(r.Writer, separator)

	// Write header
	fmt.Fprint(r.Writer, "|")
	for i, col := range cols {
		// Center the header
		padded := centerPad(col.Name, widths[i])
		fmt.Fprintf(r.Writer, " %s |", padded)
	}
	fmt.Fprintln(r.Writer)

	// Write header separator
	fmt.Fprintln(r.Writer, separator)

	// Write rows grouped by profile
	for gi, g := range groups {
		if gi > 0 {
			// Add separator between groups
			fmt.Fprintln(r.Writer, separator)
		}

		for _, row := range g.Rows {
			fmt.Fprint(r.Writer, "|")
			for i, col := range cols {
				val := r.getColValue(row, col)
				padded := leftPad(val, widths[i])
				_ = i
				fmt.Fprintf(r.Writer, " %s |", padded)
			}
			fmt.Fprintln(r.Writer)
		}
	}

	// Write bottom border
	fmt.Fprintln(r.Writer, separator)
}

func buildSeparator(widths []int) string {
	var sb strings.Builder
	sb.WriteByte('+')
	for _, w := range widths {
		sb.WriteString(strings.Repeat("-", w+2))
		sb.WriteByte('+')
	}
	return sb.String()
}

func centerPad(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func leftPad(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return s + strings.Repeat(" ", width-l)
}
