package hosts

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

const (
	StatusOn  = "on"
	StatusOff = "off"

	DefaultProfile = "default"

	endMarker      = "# end"
	hostctlComment = "# hostctl"

	Banner1 = "##################################################################"
	Banner2 = "# Content under this line is handled by hostctl. DO NOT EDIT."
)

// Row represents a single hosts entry
type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

// Profile represents a managed profile
type Profile struct {
	Name   string
	Status string
	Rows   []*Row
}

// HostsFile represents the parsed hosts file
type HostsFile struct {
	Path              string
	DefaultRows       []*Row
	DefaultLines      []string // raw lines of default section (excluding # hostctl)
	HasHostctlComment bool
	Profiles          []*Profile
	ProfileMap        map[string]*Profile
}

// Load reads and parses a hosts file
func Load(path string) (*HostsFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	hf := &HostsFile{
		Path:       path,
		ProfileMap: make(map[string]*Profile),
	}

	scanner := bufio.NewScanner(f)

	inHostctl := false
	var currentProfile *Profile
	var defaultLines []string

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if !inHostctl {
			if trimmed == hostctlComment {
				hf.HasHostctlComment = true
				inHostctl = true
				continue
			}
			// Check if this is a profile marker without # hostctl
			if isProfileMarker(trimmed) {
				inHostctl = true
				// process this line as profile marker
			} else {
				defaultLines = append(defaultLines, line)
				continue
			}
		}

		if !inHostctl {
			continue
		}

		// In hostctl section
		if trimmed == Banner1 || trimmed == Banner2 {
			continue
		}
		if trimmed == "" {
			continue
		}

		// Profile start markers
		if name, ok := parseProfileOn(trimmed); ok {
			p := &Profile{Name: name, Status: StatusOn}
			hf.Profiles = append(hf.Profiles, p)
			hf.ProfileMap[name] = p
			currentProfile = p
			continue
		}
		if name, ok := parseProfileOff(trimmed); ok {
			p := &Profile{Name: name, Status: StatusOff}
			hf.Profiles = append(hf.Profiles, p)
			hf.ProfileMap[name] = p
			currentProfile = p
			continue
		}

		if trimmed == endMarker {
			currentProfile = nil
			continue
		}

		// Parse entry line
		if currentProfile != nil {
			entryLine := trimmed
			if strings.HasPrefix(entryLine, "# ") {
				entryLine = strings.TrimPrefix(entryLine, "# ")
			}
			parts := strings.Fields(entryLine)
			if len(parts) >= 2 {
				ip := parts[0]
				for _, host := range parts[1:] {
					row := &Row{
						Profile: currentProfile.Name,
						Status:  currentProfile.Status,
						IP:      ip,
						Host:    host,
					}
					currentProfile.Rows = append(currentProfile.Rows, row)
				}
			}
		}
	}

	hf.DefaultLines = defaultLines

	// Parse default rows (only first hostname per line)
	for _, dl := range defaultLines {
		trimmed := strings.TrimSpace(dl)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		parts := strings.Fields(trimmed)
		if len(parts) >= 2 {
			hf.DefaultRows = append(hf.DefaultRows, &Row{
				Profile: DefaultProfile,
				Status:  StatusOn,
				IP:      parts[0],
				Host:    parts[1],
			})
		}
	}

	return hf, scanner.Err()
}

func isProfileMarker(s string) bool {
	_, ok1 := parseProfileOn(s)
	_, ok2 := parseProfileOff(s)
	return ok1 || ok2
}

func parseProfileOn(s string) (string, bool) {
	if strings.HasPrefix(s, "# profile.on ") {
		return strings.TrimSpace(strings.TrimPrefix(s, "# profile.on ")), true
	}
	if strings.HasPrefix(s, "# profile:on ") {
		return strings.TrimSpace(strings.TrimPrefix(s, "# profile:on ")), true
	}
	return "", false
}

func parseProfileOff(s string) (string, bool) {
	if strings.HasPrefix(s, "# profile.off ") {
		return strings.TrimSpace(strings.TrimPrefix(s, "# profile.off ")), true
	}
	if strings.HasPrefix(s, "# profile:off ") {
		return strings.TrimSpace(strings.TrimPrefix(s, "# profile:off ")), true
	}
	return "", false
}

// Save writes the hosts file to disk
func (hf *HostsFile) Save() error {
	f, err := os.Create(hf.Path)
	if err != nil {
		return err
	}
	defer f.Close()

	w := bufio.NewWriter(f)

	// Write default section lines (IP + first hostname only, skip comments and blanks)
	for _, dl := range hf.DefaultLines {
		trimmed := strings.TrimSpace(dl)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		parts := strings.Fields(trimmed)
		if len(parts) >= 2 {
			fmt.Fprintf(w, "%s %s\n", parts[0], parts[1])
		}
	}

	// Blank line
	fmt.Fprintln(w)

	// Write # hostctl comment if it was present
	if hf.HasHostctlComment {
		fmt.Fprintln(w, hostctlComment)
		fmt.Fprintln(w)
	}

	// Write banner
	fmt.Fprintln(w, Banner1)
	fmt.Fprintln(w, Banner2)
	fmt.Fprintln(w, Banner1)

	// Write profiles
	for _, p := range hf.Profiles {
		fmt.Fprintln(w)
		if p.Status == StatusOn {
			fmt.Fprintf(w, "# profile.on %s\n", p.Name)
		} else {
			fmt.Fprintf(w, "# profile.off %s\n", p.Name)
		}

		for _, row := range p.Rows {
			if p.Status == StatusOn {
				fmt.Fprintf(w, "%s %s\n", row.IP, row.Host)
			} else {
				fmt.Fprintf(w, "# %s %s\n", row.IP, row.Host)
			}
		}

		fmt.Fprintln(w, endMarker)
	}

	return w.Flush()
}

// GetAllRows returns all rows filtered by profiles
func (hf *HostsFile) GetAllRows(profileFilter []string) []*Row {
	var rows []*Row

	filterMap := make(map[string]bool)
	hasFilter := len(profileFilter) > 0
	for _, p := range profileFilter {
		filterMap[p] = true
	}

	if !hasFilter || filterMap[DefaultProfile] {
		rows = append(rows, hf.DefaultRows...)
	}

	for _, p := range hf.Profiles {
		if hasFilter && !filterMap[p.Name] {
			continue
		}
		rows = append(rows, p.Rows...)
	}

	return rows
}

// GetRowsByStatus returns rows filtered by status
func (hf *HostsFile) GetRowsByStatus(status string) []*Row {
	var rows []*Row
	rows = append(rows, hf.DefaultRows...) // default is always "on"

	for _, p := range hf.Profiles {
		if p.Status == status {
			rows = append(rows, p.Rows...)
		}
	}
	return rows
}

// GetProfile returns a profile by name
func (hf *HostsFile) GetProfile(name string) *Profile {
	return hf.ProfileMap[name]
}

// GetProfileNames returns all profile names
func (hf *HostsFile) GetProfileNames() []string {
	var names []string
	for _, p := range hf.Profiles {
		names = append(names, p.Name)
	}
	return names
}

// AddRows adds rows to a profile (creating if needed)
func (hf *HostsFile) AddRows(profileName string, rows []*Row) {
	p := hf.ProfileMap[profileName]
	if p == nil {
		p = &Profile{Name: profileName, Status: StatusOn}
		hf.Profiles = append(hf.Profiles, p)
		hf.ProfileMap[profileName] = p
	}
	for _, r := range rows {
		r.Profile = profileName
		r.Status = p.Status
		p.Rows = append(p.Rows, r)
	}
}

// ReplaceRows replaces all rows in a profile
func (hf *HostsFile) ReplaceRows(profileName string, rows []*Row) {
	// Remove existing profile
	hf.RemoveProfile(profileName)
	// Add new
	hf.AddRows(profileName, rows)
}

// RemoveProfile removes a profile
func (hf *HostsFile) RemoveProfile(name string) bool {
	if _, exists := hf.ProfileMap[name]; !exists {
		return false
	}
	delete(hf.ProfileMap, name)
	var newProfiles []*Profile
	for _, p := range hf.Profiles {
		if p.Name != name {
			newProfiles = append(newProfiles, p)
		}
	}
	hf.Profiles = newProfiles
	return true
}

// RemoveDomains removes specific domains from a profile
// Returns true if profile was removed (no more domains)
func (hf *HostsFile) RemoveDomains(profileName string, domains []string) (bool, bool) {
	p := hf.ProfileMap[profileName]
	if p == nil {
		return false, false
	}

	domainSet := make(map[string]bool)
	for _, d := range domains {
		domainSet[d] = true
	}

	var newRows []*Row
	for _, r := range p.Rows {
		if !domainSet[r.Host] {
			newRows = append(newRows, r)
		}
	}

	if len(newRows) == 0 {
		hf.RemoveProfile(profileName)
		return true, true // profileRemoved = true
	}
	p.Rows = newRows
	return true, false
}

// EnableProfile enables a profile
func (hf *HostsFile) EnableProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	p.Status = StatusOn
	for _, r := range p.Rows {
		r.Status = StatusOn
	}
	return true
}

// DisableProfile disables a profile
func (hf *HostsFile) DisableProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	p.Status = StatusOff
	for _, r := range p.Rows {
		r.Status = StatusOff
	}
	return true
}

// ToggleProfile toggles a profile's status
func (hf *HostsFile) ToggleProfile(name string) bool {
	p := hf.ProfileMap[name]
	if p == nil {
		return false
	}
	if p.Status == StatusOn {
		return hf.DisableProfile(name)
	}
	return hf.EnableProfile(name)
}

// ParseRows parses lines into rows
func ParseRows(lines []string) []*Row {
	var rows []*Row
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		parts := strings.Fields(trimmed)
		if len(parts) >= 2 {
			ip := parts[0]
			for _, host := range parts[1:] {
				rows = append(rows, &Row{IP: ip, Host: host, Status: StatusOn})
			}
		}
	}
	return rows
}
