func (r *Renderer) Render(groups []Group, cols []Column) {
	if r.Quiet {
		return
	}

	switch r.Output {
	case OutputJSON:
		r.renderJSON(groups, cols)
	case OutputRaw:
		r.renderRaw(groups, cols)
	case OutputMarkdown:
		r.renderMarkdown(groups, cols)
	default: // table
		r.renderTable(groups, cols)
	}
}

