	var rows []jsonRow
	for _, g := range groups {
		for _, row := range g.Rows {
			jr := jsonRow{
				Profile: row["profile"],
				Status:  row["status"],
				IP:      row["ip"],
				Host:    row["host"],
			}
			rows = append(rows, jr)
		}
	}
	if rows == nil {
