	for i, col := range cols {
		padded := padRight(col.Name, widths[i])
		if i < n-1 {
			fmt.Fprintf(r.Writer, "%s\t", padded)
		} else {
			// Last column: padded to width + 1 extra space + newline
			fmt.Fprintf(r.Writer, "%s \n", padded)
		}
	}

	// Data rows
	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
				v := getColVal(row, col)
				padded := padRight(v, widths[i])
				fmt.Fprintf(r.Writer, "%s\t", padded)
			}
