func (r *Renderer) renderMarkdown(groups []Group, cols []Column) {
	widths := calcWidths(groups, cols)

	// Header row
	fmt.Fprint(r.Writer, "|")
	for i, col := range cols {
		fmt.Fprintf(r.Writer, " %s |", padRight(col.Name, widths[i]))
		_ = i
	}
	fmt.Fprintln(r.Writer)

	// Separator after header
	printMarkdownSep(r.Writer, widths)

	// Data rows with separators between groups
	for gi, g := range groups {
		if gi > 0 {
