	fmt.Fprint(r.Writer, "|")
	for i, col := range cols {
		centered := centerText(col.Name, widths[i])
		fmt.Fprintf(r.Writer, " %s |", centered)
		_ = i
	}
	fmt.Fprintln(r.Writer)

	// Header separator
	fmt.Fprintln(r.Writer, sep)

	// Data rows with separators between groups
	for gi, g := range groups {
		if gi > 0 {
			fmt.Fprintln(r.Writer, sep)
		}
		for _, row := range g.Rows {
			fmt.Fprint(r.Writer, "|")
			for i, col := range cols {
				v := getColVal(row, col)
				fmt.Fprintf(r.Writer, " %s |", padRight(v, widths[i]))
				_ = i
			}
			fmt.Fprintln(r.Writer)
		}
	}

	// Bottom border
	fmt.Fprintln(r.Writer, sep)
}

func buildTableSep(widths []int) string {
	var sb strings.Builder
	sb.WriteByte('+')
	for _, w := range widths {
		for i := 0; i < w+2; i++ {
			sb.WriteByte('-')
		}
		sb.WriteByte('+')
	}
	return sb.String()
}

func centerText(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return s + strings.Repeat(" ", width-l)
}
