	OutputTable    OutputType = "table"
	OutputRaw      OutputType = "raw"
	OutputMarkdown OutputType = "markdown"
	OutputJSON     OutputType = "json"
)

// Column represents a table column definition
type Column struct {
	Name string // Display name (header)
	Key  string // Lookup key (lowercase)
}

// Row represents a table row as key-value map
type Row map[string]string

// Group is a collection of rows for one profile
type Group struct {
	Profile string
	Rows    []Row
}

// Renderer handles output rendering
type Renderer struct {
	Output  OutputType
	Writer  io.Writer
	NoColor bool
	Quiet   bool
}

// New creates a new renderer
func New(w io.Writer, output OutputType) *Renderer {
	return &Renderer{
		Output: output,
		Writer: w,
	}
}

// PrintInfo prints an info message
func (r *Renderer) PrintInfo(msg string) {
	if r.Quiet {
		return
	}
	fmt.Fprintf(r.Writer, "[ℹ] %s\n", msg)
}

// PrintSuccess prints a success message
func (r *Renderer) PrintSuccess(msg string) {
	if r.Quiet {
		return
	}
	fmt.Fprintf(r.Writer, "\n[✔] %s\n", msg)
}

// PrintError prints an error message
func (r *Renderer) PrintError(err error) {
	fmt.Fprintf(r.Writer, "\n[✖] error: %v\n", err)
}

// Render renders groups with the given columns
func (r *Renderer) Render(groups []Group, cols []Column) {
	if r.Quiet {
		return
	}

	switch r.Output {
	case OutputJSON:
		r.renderJSON(groups, cols)
	case OutputRaw:
		r.renderRaw(groups, cols)
	case OutputMarkdown:
		r.renderMarkdown(groups, cols)
	default: // table
		r.renderTable(groups, cols)
	}
}

type jsonRow struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

func (r *Renderer) renderJSON(groups []Group, cols []Column) {
	var rows []jsonRow
	for _, g := range groups {
		for _, row := range g.Rows {
			jr := jsonRow{
				Profile: row["profile"],
				Status:  row["status"],
				IP:      row["ip"],
				Host:    row["host"],
			}
			rows = append(rows, jr)
		}
	}
	if rows == nil {
