func calcWidths(groups []Group, cols []Column) []int {
	widths := make([]int, len(cols))
	for i, col := range cols {
		widths[i] = utf8.RuneCountInString(col.Name)
	}
	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
