package cli

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/guumaster/hostctl/pkg/hosts"
	"github.com/guumaster/hostctl/pkg/renderer"
)

// GlobalFlags holds global command flags
type GlobalFlags struct {
	HostFile string
	Out      string
	Columns  []string
	NoColor  bool
	Quiet    bool
	Raw      bool
}

// getOutput returns the output type, defaulting to table
func getOutput(g *GlobalFlags) renderer.OutputType {
	if g.Raw {
		return renderer.OutputRaw
	}
	switch strings.ToLower(g.Out) {
	case "raw":
		return renderer.OutputRaw
	case "markdown":
		return renderer.OutputMarkdown
	case "json":
		return renderer.OutputJSON
	default:
		return renderer.OutputTable
	}
}

// newRenderer creates a renderer with global flags
func newRenderer(g *GlobalFlags) *renderer.Renderer {
	r := renderer.New(os.Stdout, getOutput(g))
	r.NoColor = g.NoColor
	r.Quiet = g.Quiet
	return r
}

// printInfo prints the info message about which file is being used
func printInfo(r *renderer.Renderer, g *GlobalFlags) {
	if getOutput(g) == renderer.OutputJSON {
		return
	}
	r.PrintInfo(fmt.Sprintf("Using hosts file: %s", g.HostFile))
	fmt.Println()
}

// The available columns for list command
var listColumns = []renderer.Column{
	{Name: "PROFILE", Key: "profile"},
	{Name: "STATUS", Key: "status"},
	{Name: "IP", Key: "ip"},
	{Name: "DOMAIN", Key: "host"},
}

// The available columns for status command  
var statusColumns = []renderer.Column{
	{Name: "PROFILE", Key: "profile"},
	{Name: "STATUS", Key: "status"},
}

// getColumns filters columns based on the -c flag
func getColumns(g *GlobalFlags, available []renderer.Column) []renderer.Column {
	if len(g.Columns) == 0 {
		return available
	}
	var cols []renderer.Column
	for _, requested := range g.Columns {
		for _, avail := range available {
			if strings.ToLower(requested) == avail.Key || strings.ToLower(requested) == strings.ToLower(avail.Name) {
				cols = append(cols, avail)
				break
			}
		}
	}
	return cols
}

// rowsToGroups converts host rows to renderer groups
func rowsToGroups(rows []*hosts.Row) []renderer.Group {
	// Group by profile, maintaining order
	var groups []renderer.Group
	groupMap := make(map[string]*renderer.Group)
	var order []string

	for _, row := range rows {
		if _, exists := groupMap[row.Profile]; !exists {
			g := &renderer.Group{Profile: row.Profile}
			groups = append(groups, *g)
			groupMap[row.Profile] = &groups[len(groups)-1]
			order = append(order, row.Profile)
		}
		g := groupMap[row.Profile]
		g.Rows = append(g.Rows, renderer.Row{
			"profile": row.Profile,
			"status":  row.Status,
			"ip":      row.IP,
			"host":    row.Host,
		})
	}
	_ = order

	// Rebuild from groups slice (it's been modified via pointer)
	return groups
}

// profileToGroups converts profiles to renderer groups (for status command)
func profileToGroups(profiles []*hosts.Profile) []renderer.Group {
	var groups []renderer.Group
	for _, p := range profiles {
		g := renderer.Group{Profile: p.Name}
		g.Rows = append(g.Rows, renderer.Row{
			"profile": p.Name,
			"status":  p.Status,
			"ip":      "",
			"host":    "",
		})
		groups = append(groups, g)
	}
	return groups
}

// printTable renders the table output
func printTable(r *renderer.Renderer, groups []renderer.Group, g *GlobalFlags, available []renderer.Column) {
	cols := getColumns(g, available)
	if getOutput(g) != renderer.OutputJSON {
		fmt.Println()
	}
	r.Render(groups, cols)
	if getOutput(g) != renderer.OutputJSON {
		fmt.Println()
	}
}

// CmdList handles the list command
func CmdList(g *GlobalFlags, profiles []string, statusFilter string) error {
	r := newRenderer(g)
	printInfo(r, g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	var rows []*hosts.Row
	if statusFilter == "enabled" {
		rows = hf.GetRowsByStatus(hosts.StatusOn)
	} else if statusFilter == "disabled" {
		rows = hf.GetRowsByStatus(hosts.StatusOff)
		// Also include default rows
		if statusFilter == "disabled" {
			// GetRowsByStatus already includes default for "enabled"
			// For "disabled" we need to include default rows manually
			// Actually looking at the behavior: list disabled includes default + all disabled
			// So we include default separately
		}
	} else {
		rows = hf.GetAllRows(profiles)
	}

	groups := rowsToGroups(rows)
	printTable(r, groups, g, listColumns)
	return nil
}

// CmdStatus handles the status command
func CmdStatus(g *GlobalFlags, profiles []string) error {
	r := newRenderer(g)
	printInfo(r, g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	var filteredProfiles []*hosts.Profile
	if len(profiles) > 0 {
		for _, name := range profiles {
			if p := hf.GetProfile(name); p != nil {
				filteredProfiles = append(filteredProfiles, p)
			}
		}
	} else {
		filteredProfiles = hf.Profiles
	}

	groups := profileToGroups(filteredProfiles)
	printTable(r, groups, g, statusColumns)
	return nil
}

// CmdEnable handles the enable command
func CmdEnable(g *GlobalFlags, profiles []string, all bool, only bool, wait time.Duration) error {
	r := newRenderer(g)
	printInfo(r, g)

	if !all && len(profiles) == 0 {
		r.PrintError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	if only {
		// Disable all others first
		for _, p := range hf.Profiles {
			hf.DisableProfile(p.Name)
		}
	}

	if all {
		for _, p := range hf.Profiles {
			hf.EnableProfile(p.Name)
		}
	} else {
		for _, name := range profiles {
			if !hf.EnableProfile(name) {
				r.PrintError(fmt.Errorf("unknown profile name"))
				return fmt.Errorf("unknown profile name")
			}
		}
	}

	if err := hf.Save(); err != nil {
		r.PrintError(err)
		return err
	}

	// Show the affected profiles
	var rows []*hosts.Row
	if all {
		rows = hf.GetAllRows(nil)
	} else {
		rows = hf.GetAllRows(profiles)
	}
	groups := rowsToGroups(rows)
	printTable(r, groups, g, listColumns)

	if wait > 0 {
		profileList := strings.Join(profiles, ", ")
		if all {
			profileList = "all"
		}
		r.PrintInfo(fmt.Sprintf("Waiting for %s or ctrl+c to disable from profile '%s'", formatDuration(wait), profileList))
		fmt.Println()
		fmt.Println()
		fmt.Println()
		time.Sleep(wait)
		return CmdDisable(g, profiles, all, false, -1)
	}

	return nil
}

// CmdDisable handles the disable command
func CmdDisable(g *GlobalFlags, profiles []string, all bool, only bool, wait time.Duration) error {
	r := newRenderer(g)

	if wait >= 0 {
		// Only print info on first call
		printInfo(r, g)
	}

	if !all && len(profiles) == 0 {
		r.PrintError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	if only {
		// Enable all others first
		for _, p := range hf.Profiles {
			hf.EnableProfile(p.Name)
		}
	}

	if all {
		for _, p := range hf.Profiles {
			hf.DisableProfile(p.Name)
		}
	} else {
		for _, name := range profiles {
			if !hf.DisableProfile(name) {
				r.PrintError(fmt.Errorf("unknown profile name"))
				return fmt.Errorf("unknown profile name")
			}
		}
	}

	if err := hf.Save(); err != nil {
		r.PrintError(err)
		return err
	}

	// Show the affected profiles
	var rows []*hosts.Row
	if all {
		rows = hf.GetAllRows(nil)
	} else {
		rows = hf.GetAllRows(profiles)
	}
	groups := rowsToGroups(rows)
	printTable(r, groups, g, listColumns)

	if wait > 0 {
		profileList := strings.Join(profiles, ", ")
		if all {
			profileList = "all"
		}
		r.PrintInfo(fmt.Sprintf("Waiting for %s or ctrl+c to enable from profile '%s'", formatDuration(wait), profileList))
		fmt.Println()
		fmt.Println()
		fmt.Println()
		time.Sleep(wait)
		return CmdEnable(g, profiles, all, false, -1)
	}

	return nil
}

// CmdToggle handles the toggle command
func CmdToggle(g *GlobalFlags, profiles []string, wait time.Duration) error {
	r := newRenderer(g)
	printInfo(r, g)

	if len(profiles) == 0 {
		r.PrintError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	for _, name := range profiles {
		if !hf.ToggleProfile(name) {
			r.PrintError(fmt.Errorf("unknown profile name"))
			return fmt.Errorf("unknown profile name")
		}
	}

	if err := hf.Save(); err != nil {
		r.PrintError(err)
		return err
	}

	rows := hf.GetAllRows(profiles)
	groups := rowsToGroups(rows)
	printTable(r, groups, g, listColumns)

	if wait > 0 {
		// Determine what we toggled to, and wait to toggle back
		// We need to re-load to check current status
		hf2, _ := hosts.Load(g.HostFile)
		var action string
		for _, name := range profiles {
			if p := hf2.GetProfile(name); p != nil {
				if p.Status == hosts.StatusOn {
					action = "disable"
				} else {
					action = "enable"
				}
				break
			}
		}
		profileList := strings.Join(profiles, ", ")
		r.PrintInfo(fmt.Sprintf("Waiting for %s or ctrl+c to %s from profile '%s'", formatDuration(wait), action, profileList))
		fmt.Println()
		fmt.Println()
		fmt.Println()
		time.Sleep(wait)
		return CmdToggle(g, profiles, -1)
	}

	return nil
}

// CmdRemove handles the remove command (profiles)
func CmdRemove(g *GlobalFlags, profiles []string, all bool) error {
	r := newRenderer(g)
	printInfo(r, g)

	if !all && len(profiles) == 0 {
		r.PrintError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	var removed []string
	if all {
		for _, p := range hf.GetProfileNames() {
			if hf.RemoveProfile(p) {
				removed = append(removed, p)
			}
		}
	} else {
		for _, name := range profiles {
			if hf.RemoveProfile(name) {
				removed = append(removed, name)
			}
		}
	}

	if err := hf.Save(); err != nil {
		r.PrintError(err)
		return err
	}

	r.PrintSuccess(fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(removed, ", ")))
	fmt.Println()
	fmt.Println()
	return nil
}

// CmdRemoveDomains handles the remove domains command
func CmdRemoveDomains(g *GlobalFlags, profileName string, domains []string) error {
	r := newRenderer(g)
	printInfo(r, g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
		return err
	}

	ok, profileRemoved := hf.RemoveDomains(profileName, domains)
	if !ok {
		r.PrintError(fmt.Errorf("unknown profile name"))
		return fmt.Errorf("unknown profile name")
	}

	if err := hf.Save(); err != nil {
		r.PrintError(err)
		return err
	}

	if profileRemoved {
		r.PrintSuccess(fmt.Sprintf("Profile '%s' removed.", profileName))
		fmt.Println()
		fmt.Println()
		return nil
	}

	r.PrintSuccess(fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))

	rows := hf.GetAllRows([]string{profileName})
	groups := rowsToGroups(rows)
	printTable(r, groups, g, listColumns)
	return nil
}

// CmdAddDomains handles the add domains command
func CmdAddDomains(g *GlobalFlags, profileName string, domains []string, ip string, wait time.Duration) error {
	r := newRenderer(g)
	printInfo(r, g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		r.PrintError(err)
