func parseDockerCompose(filename string) ([]dockerComposeService, error) {
	// We need to parse YAML - but we don't have a YAML library
	// Let's use the Docker API directly to get container info
	f, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	// Simple YAML parsing for services
	var services []dockerComposeService
	scanner := bufio.NewScanner(f)

	inServices := false
	inService := false
	currentService := ""
	inNetworks := false
	currentNetworks := []string{}

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if trimmed == "services:" {
			inServices = true
			continue
		}

		if inServices && !strings.HasPrefix(line, " ") && !strings.HasPrefix(line, "\t") && trimmed != "" && !strings.HasPrefix(trimmed, "#") {
			if trimmed != "services:" {
				inServices = false
			}
		}

		if inServices {
			// Service name is indented with 2 spaces
			if strings.HasPrefix(line, "  ") && !strings.HasPrefix(line, "    ") {
				if inService && currentService != "" {
					services = append(services, dockerComposeService{Name: currentService, Networks: currentNetworks})
				}
				currentService = strings.TrimSuffix(trimmed, ":")
				currentNetworks = []string{}
				inService = true
				inNetworks = false
			} else if inService && strings.HasPrefix(line, "    networks:") {
				inNetworks = true
			} else if inNetworks && strings.HasPrefix(line, "      - ") {
				net := strings.TrimPrefix(trimmed, "- ")
				currentNetworks = append(currentNetworks, net)
			} else if inNetworks && !strings.HasPrefix(line, "      ") {
				inNetworks = false
			}
		}
	}

	if inService && currentService != "" {
		services = append(services, dockerComposeService{Name: currentService, Networks: currentNetworks})
	}

	return services, nil
}

