// getOutput returns the output type, defaulting to table
func getOutput(g *GlobalFlags) renderer.OutputType {
	if g.Raw {
		return renderer.OutputRaw
	}
	switch strings.ToLower(g.Out) {
	case "raw":
		return renderer.OutputRaw
	case "markdown":
		return renderer.OutputMarkdown
	case "json":
		return renderer.OutputJSON
	default:
		return renderer.OutputTable
	}
}

// newRenderer creates a renderer with global flags
func newRenderer(g *GlobalFlags) *renderer.Renderer {
	r := renderer.New(os.Stdout, getOutput(g))
	r.NoColor = g.NoColor
	r.Quiet = g.Quiet
	return r
}

// printInfo prints the info message about which file is being used
func printInfo(r *renderer.Renderer, g *GlobalFlags) {
	if getOutput(g) == renderer.OutputJSON {
		return
	}
