		hf2, _ := hosts.Load(g.HostFile)
		var action string
		for _, name := range profiles {
			if p := hf2.GetProfile(name); p != nil {
				if p.Status == hosts.StatusOn {
					action = "disable"
				} else {
					action = "enable"
				}
				break
			}
		}
		profileList := strings.Join(profiles, ", ")
		r.PrintInfo(fmt.Sprintf("Waiting for %s or ctrl+c to %s from profile '%s'", formatDuration(wait), action, profileList))
		fmt.Println()
		fmt.Println()
		fmt.Println()
		time.Sleep(wait)
		return CmdToggle(g, profiles, -1)
	}

	return nil
}

