// GlobalFlags holds global command flags
type GlobalFlags struct {
	HostFile string
	Out      string
	Columns  []string
	NoColor  bool
	Quiet    bool
	Raw      bool
}

// getOutput returns the output type, defaulting to table
func getOutput(g *GlobalFlags) renderer.OutputType {
	if g.Raw {
		return renderer.OutputRaw
	}
	switch strings.ToLower(g.Out) {
	case "raw":
		return renderer.OutputRaw
	case "markdown":
		return renderer.OutputMarkdown
	case "json":
		return renderer.OutputJSON
	default:
		return renderer.OutputTable
	}
}

// newRenderer creates a renderer with global flags
func newRenderer(g *GlobalFlags) *renderer.Renderer {
	r := renderer.New(os.Stdout, getOutput(g))
	r.NoColor = g.NoColor
	r.Quiet = g.Quiet
	return r
}

// printInfo prints the info message about which file is being used
func printInfo(r *renderer.Renderer, g *GlobalFlags) {
	if getOutput(g) == renderer.OutputJSON {
		return
	}
	r.PrintInfo(fmt.Sprintf("Using hosts file: %s", g.HostFile))
	fmt.Println()
}

// The available columns for list command
var listColumns = []renderer.Column{
	{Name: "PROFILE", Key: "profile"},
	{Name: "STATUS", Key: "status"},
	{Name: "IP", Key: "ip"},
	{Name: "DOMAIN", Key: "host"},
}

// The available columns for status command  
var statusColumns = []renderer.Column{
	{Name: "PROFILE", Key: "profile"},
	{Name: "STATUS", Key: "status"},
}

// getColumns filters columns based on the -c flag
func getColumns(g *GlobalFlags, available []renderer.Column) []renderer.Column {
	if len(g.Columns) == 0 {
		return available
	}
	var cols []renderer.Column
	for _, requested := range g.Columns {
		for _, avail := range available {
			if strings.ToLower(requested) == avail.Key || strings.ToLower(requested) == strings.ToLower(avail.Name) {
				cols = append(cols, avail)
				break
			}
		}
	}
	return cols
}

// rowsToGroups converts host rows to renderer groups
func rowsToGroups(rows []*hosts.Row) []renderer.Group {
	// Group by profile, maintaining order
	var groups []renderer.Group
	groupMap := make(map[string]*renderer.Group)
	var order []string

	for _, row := range rows {
		if _, exists := groupMap[row.Profile]; !exists {
			g := &renderer.Group{Profile: row.Profile}
			groups = append(groups, *g)
			groupMap[row.Profile] = &groups[len(groups)-1]
			order = append(order, row.Profile)
		}
		g := groupMap[row.Profile]
		g.Rows = append(g.Rows, renderer.Row{
			"profile": row.Profile,
			"status":  row.Status,
			"ip":      row.IP,
			"host":    row.Host,
		})
	}
	_ = order

	// Rebuild from groups slice (it's been modified via pointer)
	return groups
}

// profileToGroups converts profiles to renderer groups (for status command)
func profileToGroups(profiles []*hosts.Profile) []renderer.Group {
	var groups []renderer.Group
	for _, p := range profiles {
		g := renderer.Group{Profile: p.Name}
		g.Rows = append(g.Rows, renderer.Row{
			"profile": p.Name,
			"status":  p.Status,
			"ip":      "",
			"host":    "",
		})
		groups = append(groups, g)
	}
	return groups
}

// printTable renders the table output
func printTable(r *renderer.Renderer, groups []renderer.Group, g *GlobalFlags, available []renderer.Column) {
	cols := getColumns(g, available)
	if getOutput(g) != renderer.OutputJSON {
		fmt.Println()
	}
	r.Render(groups, cols)
	if getOutput(g) != renderer.OutputJSON {
		fmt.Println()
	}
}

