func CmdToggle(g *GlobalFlags, profiles []string, wait time.Duration) error {
	r := newRenderer(g)
	printInfo(r, g)

	if len(profiles) == 0 {
		r.PrintError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
