// readInput reads from a file or stdin
func readInput(filename string) ([]string, error) {
	var f io.Reader
	if filename != "" {
		file, err := os.Open(filename)
		if err != nil {
			return nil, err
		}
		defer file.Close()
		f = file
	} else {
		// Check if stdin is a terminal (no pipe)
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			// stdin is a terminal, not pipe
			return nil, fmt.Errorf("open : no such file or directory")
		}
		f = os.Stdin
	}

	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines, scanner.Err()
}

// copyFile copies src to dst
func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	_, err = io.Copy(out, in)
	return err
}

// formatDuration formats a duration for display
func formatDuration(d time.Duration) string {
	if d.Hours() >= 1 {
		h := int(d.Hours())
		m := int(d.Minutes()) % 60
		if m > 0 {
			return fmt.Sprintf("%dh%dm0s", h, m)
		}
		return fmt.Sprintf("%dh0m0s", h)
	}
	if d.Minutes() >= 1 {
		m := int(d.Minutes())
		s := int(d.Seconds()) % 60
		if s > 0 {
			return fmt.Sprintf("%dm%ds", m, s)
		}
		return fmt.Sprintf("%dm0s", m)
	}
	return fmt.Sprintf("%gs", d.Seconds())
}

