// duration is a flag.Value for time.Duration with default -1ns
type duration struct {
	d time.Duration
}

func (d *duration) String() string {
	return d.d.String()
}

func (d *duration) Set(s string) error {
	v, err := time.ParseDuration(s)
	if err != nil {
		return err
	}
	d.d = v
	return nil
}

