	// add [profile] --from file
	fs := flag.NewFlagSet("add", flag.ContinueOnError)
	fs.SetOutput(os.Stdout)

	fromFile := fs.String("from", "", "file to read")
	fromFile2 := fs.String("f", "", "file to read")
	var waitDur duration
	waitDur.d = -1
	fs.Var(&waitDur, "wait", "Enables a profile for a specific amount of time")
	fs.Var(&waitDur, "w", "Enables a profile for a specific amount of time")

	g, remaining, err := parseGlobal(fs, args)
	if err != nil {
