	}

	if len(remaining) == 0 {
		r := getRendererForError(g)
		r.PrintError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	return cli.CmdAddFromFile(g, remaining[0], from, waitDur.d)
