package main

import (
	"flag"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/guumaster/hostctl/pkg/cli"
)

const version = "dev"

func main() {
	if err := run(os.Args[1:]); err != nil {
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) == 0 {
		printUsage()
		return nil
	}

	switch args[0] {
	case "--help", "-h":
		printUsage()
		return nil
	case "--version", "-v":
		fmt.Printf("\nhostctl version %s\n", version)
		return nil
	case "help":
		if len(args) > 1 {
			return showCommandHelp(args[1])
		}
		printUsage()
		return nil
	case "list":
		return runList(args[1:])
	case "status":
		return runStatus(args[1:])
	case "enable":
		return runEnable(args[1:])
	case "disable":
		return runDisable(args[1:])
	case "toggle":
		return runToggle(args[1:])
	case "add":
		return runAdd(args[1:])
	case "remove", "rm":
		return runRemove(args[1:])
	case "replace":
		return runReplace(args[1:])
	case "backup":
		return runBackup(args[1:])
	case "restore":
		return runRestore(args[1:])
	case "sync":
		return runSync(args[1:])
	default:
		fmt.Fprintf(os.Stderr, "Error: unknown command \"%s\" for \"hostctl\"\nRun 'hostctl --help' for usage.\n", args[0])
		return fmt.Errorf("unknown command")
	}
}

func parseGlobal(fs *flag.FlagSet, args []string) (*cli.GlobalFlags, []string, error) {
	g := &cli.GlobalFlags{}

	fs.StringVar(&g.HostFile, "host-file", "/etc/hosts", "Hosts file path")
	fs.StringVar(&g.Out, "out", "table", "Output type (table|raw|markdown|json)")
	fs.StringVar(&g.Out, "o", "table", "Output type (table|raw|markdown|json)")
	fs.BoolVar(&g.NoColor, "no-color", false, "force colorless output")
	fs.BoolVar(&g.Quiet, "quiet", false, "Run command without output")
	fs.BoolVar(&g.Quiet, "q", false, "Run command without output")
	fs.BoolVar(&g.Raw, "raw", false, "Output without borders (same as -o raw)")

	var columnsStr string
	fs.StringVar(&columnsStr, "column", "", "Column names to show on lists. comma separated")
	fs.StringVar(&columnsStr, "c", "", "Column names to show on lists. comma separated")

	if err := fs.Parse(args); err != nil {
		return nil, nil, err
	}

	if columnsStr != "" {
		g.Columns = strings.Split(columnsStr, ",")
		for i, c := range g.Columns {
			g.Columns[i] = strings.TrimSpace(c)
		}
	}

	return g, fs.Args(), nil
}

func runList(args []string) error {
	fs := flag.NewFlagSet("list", flag.ContinueOnError)
	fs.SetOutput(os.Stdout)

	g, remaining, err := parseGlobal(fs, args)
	if err != nil {
		return err
	}

	// Check for subcommands: enabled, disabled
	if len(remaining) > 0 {
		switch remaining[0] {
		case "enabled":
			return cli.CmdList(g, nil, "enabled")
		case "disabled":
			return cli.CmdList(g, nil, "disabled")
		case "--help", "-h", "help":
			printListHelp()
			return nil
		}
	}

	return cli.CmdList(g, remaining, "")
}

