package cli

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/guumaster/hostctl/pkg/hosts"
	"github.com/guumaster/hostctl/pkg/renderer"
)

// GlobalFlags holds global command flags
type GlobalFlags struct {
	HostFile string
	Out      string
	Columns  []string
	NoColor  bool
	Quiet    bool
	Raw      bool
}

// getOutput returns the output type
func getOutput(g *GlobalFlags) renderer.OutputType {
	if g.Raw {
		return renderer.OutputRaw
	}
	switch strings.ToLower(g.Out) {
	case "raw":
		return renderer.OutputRaw
	case "markdown":
		return renderer.OutputMarkdown
	case "json":
		return renderer.OutputJSON
	default:
		return renderer.OutputTable
	}
}

// printInfo prints the info message about which file is being used
func printInfo(g *GlobalFlags) {
	if g.Quiet || getOutput(g) == renderer.OutputJSON {
		return
	}
	fmt.Printf("[ℹ] Using hosts file: %s\n\n", g.HostFile)
}

// printSuccess prints a success message
func printSuccess(g *GlobalFlags, msg string) {
	if g.Quiet {
		return
	}
	fmt.Printf("[✔] %s\n\n", msg)
}

// printError prints an error message
func printError(err error) {
	fmt.Printf("[✖] error: %v\n", err)
}

// The available columns for list command
var listColumns = []renderer.Column{
	{Name: "PROFILE", Key: "profile"},
	{Name: "STATUS", Key: "status"},
	{Name: "IP", Key: "ip"},
	{Name: "DOMAIN", Key: "host"},
}

// The available columns for status command  
var statusColumns = []renderer.Column{
	{Name: "PROFILE", Key: "profile"},
	{Name: "STATUS", Key: "status"},
}

// getColumns filters columns based on the -c flag
func getColumns(g *GlobalFlags, available []renderer.Column) []renderer.Column {
	if len(g.Columns) == 0 {
		return available
	}
	var cols []renderer.Column
	for _, requested := range g.Columns {
		lc := strings.ToLower(requested)
		for _, avail := range available {
			if lc == avail.Key {
				cols = append(cols, avail)
				break
			}
		}
	}
	return cols
}

// rowsToGroups converts host rows to renderer groups
func rowsToGroups(rows []*hosts.Row) []renderer.Group {
	var groups []renderer.Group
	groupIdx := make(map[string]int)

	for _, row := range rows {
		idx, exists := groupIdx[row.Profile]
		if !exists {
			groups = append(groups, renderer.Group{Profile: row.Profile})
			idx = len(groups) - 1
			groupIdx[row.Profile] = idx
		}
		groups[idx].Rows = append(groups[idx].Rows, renderer.Row{
			"profile": row.Profile,
			"status":  row.Status,
			"ip":      row.IP,
			"host":    row.Host,
		})
	}

	return groups
}

// profileToGroups converts profiles to renderer groups (for status command)
func profileToGroups(profiles []*hosts.Profile) []renderer.Group {
	var groups []renderer.Group
	for _, p := range profiles {
		g := renderer.Group{Profile: p.Name}
		g.Rows = append(g.Rows, renderer.Row{
			"profile": p.Name,
			"status":  p.Status,
			"ip":      "",
			"host":    "",
		})
		groups = append(groups, g)
	}
	return groups
}

// printTable renders the table and adds trailing blank line
func printTable(g *GlobalFlags, groups []renderer.Group, available []renderer.Column) {
	if g.Quiet {
		return
	}
	cols := getColumns(g, available)
	outType := getOutput(g)

	switch outType {
	case renderer.OutputJSON:
		renderJSON(groups, cols)
	case renderer.OutputRaw:
		renderRaw(groups, cols)
	case renderer.OutputMarkdown:
		renderMarkdown(groups, cols)
		fmt.Println()
	default: // table
		renderTable(groups, cols)
		fmt.Println()
	}
}

// CmdList handles the list command
func CmdList(g *GlobalFlags, profiles []string, statusFilter string) error {
	printInfo(g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	var rows []*hosts.Row
	if statusFilter == "enabled" {
		rows = hf.GetRowsByStatus(hosts.StatusOn)
	} else if statusFilter == "disabled" {
		rows = hf.GetRowsByStatus(hosts.StatusOff)
	} else {
		rows = hf.GetAllRows(profiles)
	}

	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)
	return nil
}

// CmdStatus handles the status command
func CmdStatus(g *GlobalFlags, profiles []string) error {
	printInfo(g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	var filteredProfiles []*hosts.Profile
	if len(profiles) > 0 {
		for _, name := range profiles {
			if p := hf.GetProfile(name); p != nil {
				filteredProfiles = append(filteredProfiles, p)
			}
		}
	} else {
		filteredProfiles = hf.Profiles
	}

	groups := profileToGroups(filteredProfiles)
	printTable(g, groups, statusColumns)
	return nil
}

// CmdEnable handles the enable command
func CmdEnable(g *GlobalFlags, profiles []string, all bool, only bool, wait time.Duration) error {
	printInfo(g)

	if !all && len(profiles) == 0 {
		printError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	if only {
		for _, p := range hf.Profiles {
			hf.DisableProfile(p.Name)
		}
	}

	if all {
		for _, p := range hf.Profiles {
			hf.EnableProfile(p.Name)
		}
	} else {
		for _, name := range profiles {
			if !hf.EnableProfile(name) {
				printError(fmt.Errorf("unknown profile name"))
				return fmt.Errorf("unknown profile name")
			}
		}
	}

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	var rows []*hosts.Row
	if all {
		rows = hf.GetAllRows(nil)
	} else {
		rows = hf.GetAllRows(profiles)
	}
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)

	if wait > 0 {
		profileList := strings.Join(profiles, ", ")
		if all {
			profileList = "all"
		}
		if !g.Quiet {
			fmt.Printf("[ℹ] Waiting for %s or ctrl+c to disable from profile '%s'\n\n\n\n", formatDuration(wait), profileList)
		}
		time.Sleep(wait)
		return disableAfterWait(g, profiles, all)
	}

	return nil
}

