// CmdToggle handles the toggle command
func CmdToggle(g *GlobalFlags, profiles []string, wait time.Duration) error {
	printInfo(g)

	if len(profiles) == 0 {
		printError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	for _, name := range profiles {
		if !hf.ToggleProfile(name) {
			printError(fmt.Errorf("unknown profile name"))
			return fmt.Errorf("unknown profile name")
		}
	}

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	rows := hf.GetAllRows(profiles)
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)

	if wait > 0 {
		profileList := strings.Join(profiles, ", ")
		if !g.Quiet {
			fmt.Printf("[ℹ] Waiting for %s or ctrl+c to toggle from profile '%s'\n\n\n\n", formatDuration(wait), profileList)
		}
		time.Sleep(wait)
		return toggleAfterWait(g, profiles)
	}

	return nil
}

// toggleAfterWait toggles back after wait
func toggleAfterWait(g *GlobalFlags, profiles []string) error {
	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	for _, name := range profiles {
		hf.ToggleProfile(name)
	}

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	rows := hf.GetAllRows(profiles)
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)
	return nil
}

// CmdRemove handles the remove command (profiles)
func CmdRemove(g *GlobalFlags, profiles []string, all bool) error {
	printInfo(g)

	if !all && len(profiles) == 0 {
		printError(fmt.Errorf("missing profile name"))
		return fmt.Errorf("missing profile name")
	}

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	var removed []string
	if all {
		for _, p := range hf.GetProfileNames() {
			if hf.RemoveProfile(p) {
				removed = append(removed, p)
			}
		}
	} else {
		for _, name := range profiles {
			if hf.RemoveProfile(name) {
				removed = append(removed, name)
			}
		}
	}

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	printSuccess(g, fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(removed, ", ")))
	fmt.Println()
	return nil
}

// CmdRemoveDomains handles the remove domains command
func CmdRemoveDomains(g *GlobalFlags, profileName string, domains []string) error {
	printInfo(g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	ok, profileRemoved := hf.RemoveDomains(profileName, domains)
	if !ok {
		printError(fmt.Errorf("unknown profile name"))
		return fmt.Errorf("unknown profile name")
	}

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	if profileRemoved {
		printSuccess(g, fmt.Sprintf("Profile '%s' removed.", profileName))
		fmt.Println()
		return nil
	}

	printSuccess(g, fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))

	rows := hf.GetAllRows([]string{profileName})
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)
	return nil
}

// CmdAddDomains handles the add domains command
func CmdAddDomains(g *GlobalFlags, profileName string, domains []string, ip string, wait time.Duration) error {
	printInfo(g)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	var newRows []*hosts.Row
	for _, d := range domains {
		newRows = append(newRows, &hosts.Row{IP: ip, Host: d})
	}

	hf.AddRows(profileName, newRows)

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	printSuccess(g, fmt.Sprintf("Domains '%s' added.", strings.Join(domains, ", ")))

	rows := hf.GetAllRows([]string{profileName})
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)

	if wait > 0 {
		profileList := fmt.Sprintf("%s, %s", profileName, strings.Join(domains, ", "))
		if !g.Quiet {
			fmt.Printf("[ℹ] Waiting for %s or ctrl+c to remove domains from profile '%s'\n\n\n\n", formatDuration(wait), profileList)
		}
		time.Sleep(wait)
		return removeDomainAfterWait(g, profileName, domains)
	}

	return nil
}

func removeDomainAfterWait(g *GlobalFlags, profileName string, domains []string) error {
	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	ok, profileRemoved := hf.RemoveDomains(profileName, domains)
	if !ok || profileRemoved {
		if err := hf.Save(); err != nil {
			printError(err)
			return err
		}
		return nil
	}

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	printSuccess(g, fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))

	rows := hf.GetAllRows([]string{profileName})
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)
	return nil
}

// CmdAddFromFile handles the add command with --from flag
func CmdAddFromFile(g *GlobalFlags, profileName string, fromFile string, wait time.Duration) error {
	printInfo(g)

	input, err := readInput(fromFile)
	if err != nil {
		printError(err)
		return err
	}

	newRows := hosts.ParseRows(input)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	hf.AddRows(profileName, newRows)

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	rows := hf.GetAllRows([]string{profileName})
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)

	if wait > 0 {
		if !g.Quiet {
			fmt.Printf("[ℹ] Waiting for %s or ctrl+c to disable from profile '%s'\n\n\n\n", formatDuration(wait), profileName)
		}
		time.Sleep(wait)
		return CmdRemove(g, []string{profileName}, false)
	}

	return nil
}

// CmdReplace handles the replace command
func CmdReplace(g *GlobalFlags, profileName string, fromFile string) error {
	printInfo(g)

	input, err := readInput(fromFile)
	if err != nil {
		printError(err)
		return err
	}

	newRows := hosts.ParseRows(input)

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	hf.ReplaceRows(profileName, newRows)

	if err := hf.Save(); err != nil {
		printError(err)
		return err
	}

	rows := hf.GetAllRows([]string{profileName})
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)

	return nil
}

// CmdBackup handles the backup command
func CmdBackup(g *GlobalFlags, backupPath string) error {
	printInfo(g)

	now := time.Now()
	dateStr := now.Format("20060102")

	// Get just the filename part
	hostFileName := g.HostFile
	for i := len(hostFileName) - 1; i >= 0; i-- {
		if hostFileName[i] == '/' || hostFileName[i] == '\\' {
			hostFileName = hostFileName[i+1:]
			break
		}
	}

	backupFile := backupPath + "/" + hostFileName + "." + dateStr

	if err := copyFile(g.HostFile, backupFile); err != nil {
		printError(err)
		return err
	}

	printSuccess(g, fmt.Sprintf("Backup '%s' created.", backupFile))

	hf, err := hosts.Load(g.HostFile)
	if err != nil {
		printError(err)
		return err
	}

	rows := hf.GetAllRows(nil)
	groups := rowsToGroups(rows)
	printTable(g, groups, listColumns)

	return nil
}

// CmdRestore handles the restore command
func CmdRestore(g *GlobalFlags, fromFile string) error {
	printInfo(g)

	if err := copyFile(fromFile, g.HostFile); err != nil {
		printError(err)
		return err
