// Table rendering functions

func calcWidths(groups []renderer.Group, cols []renderer.Column) []int {
	widths := make([]int, len(cols))
	for i, col := range cols {
		widths[i] = utf8.RuneCountInString(col.Name)
	}
	for _, g := range groups {
		for _, row := range g.Rows {
			for i, col := range cols {
				v := row[col.Key]
				if l := utf8.RuneCountInString(v); l > widths[i] {
					widths[i] = l
				}
			}
		}
	}
	return widths
}

func renderJSON(groups []renderer.Group, cols []renderer.Column) {
	type jsonRow struct {
		Profile string `json:"Profile"`
		Status  string `json:"Status"`
		IP      string `json:"IP"`
		Host    string `json:"Host"`
	}
	var rows []jsonRow
	for _, g := range groups {
		for _, row := range g.Rows {
			rows = append(rows, jsonRow{
				Profile: row["profile"],
				Status:  row["status"],
				IP:      row["ip"],
				Host:    row["host"],
			})
		}
	}
	if rows == nil {
		rows = []jsonRow{}
	}

	// Build JSON manually to match expected output format
	fmt.Print("[")
	for i, r := range rows {
		if i > 0 {
			fmt.Print(",")
		}
		fmt.Printf(`{"Profile":%s,"Status":%s,"IP":%s,"Host":%s}`,
			jsonString(r.Profile), jsonString(r.Status), jsonString(r.IP), jsonString(r.Host))
	}
	fmt.Println("]")
}

func jsonString(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `\"`) + `"`
}

func renderRaw(groups []renderer.Group, cols []renderer.Column) {
	widths := calcWidths(groups, cols)
	n := len(cols)

	// Header row
	for i, col := range cols {
		padded := padRight(col.Name, widths[i])
		if i < n-1 {
			fmt.Printf("%s\t", padded)
		} else {
			fmt.Printf("%s \n", padded)
		}
	}

	// Data rows
	for _, g := range groups {
		for _, row := range g.Rows {
			for _, col := range cols {
				v := row[col.Key]
				padded := padRight(v, widths[indexCol(cols, col)])
				fmt.Printf("%s\t", padded)
			}
			fmt.Println()
		}
	}
}

func indexCol(cols []renderer.Column, col renderer.Column) int {
	for i, c := range cols {
		if c.Key == col.Key {
			return i
		}
	}
	return 0
}

func renderMarkdown(groups []renderer.Group, cols []renderer.Column) {
	widths := calcWidths(groups, cols)

	// Header row
	fmt.Print("|")
	for _, col := range cols {
		fmt.Printf(" %s |", padRight(col.Name, widths[indexCol(cols, col)]))
	}
	fmt.Println()

	// Separator after header
	printMarkdownSep(widths)

	// Data rows
	for gi, g := range groups {
		if gi > 0 {
			printMarkdownSep(widths)
		}
		for _, row := range g.Rows {
			fmt.Print("|")
			for _, col := range cols {
				v := row[col.Key]
				fmt.Printf(" %s |", padRight(v, widths[indexCol(cols, col)]))
			}
			fmt.Println()
		}
	}
}

func printMarkdownSep(widths []int) {
	fmt.Print("|")
	for _, w := range widths {
		fmt.Printf("%s|", strings.Repeat("-", w+2))
	}
	fmt.Println()
}

func renderTable(groups []renderer.Group, cols []renderer.Column) {
	widths := calcWidths(groups, cols)
	sep := buildTableSep(widths)

	fmt.Println(sep)

	// Header (centered)
	fmt.Print("|")
	for _, col := range cols {
		centered := centerText(col.Name, widths[indexCol(cols, col)])
		fmt.Printf(" %s |", centered)
	}
	fmt.Println()

	fmt.Println(sep)

	for gi, g := range groups {
		if gi > 0 {
			fmt.Println(sep)
		}
		for _, row := range g.Rows {
			fmt.Print("|")
			for _, col := range cols {
				v := row[col.Key]
				fmt.Printf(" %s |", padRight(v, widths[indexCol(cols, col)]))
			}
			fmt.Println()
		}
	}

	fmt.Println(sep)
}

func buildTableSep(widths []int) string {
	var sb strings.Builder
	sb.WriteByte('+')
	for _, w := range widths {
		for i := 0; i < w+2; i++ {
			sb.WriteByte('-')
		}
		sb.WriteByte('+')
	}
	return sb.String()
}

func centerText(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	total := width - l
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	l := utf8.RuneCountInString(s)
	if l >= width {
		return s
	}
	return s + strings.Repeat(" ", width-l)
}
