// Arg represents a parsed argument
type FlagSet struct {
	flags    map[string]*flagDef
	args     []string
	parsed   bool
	errorMsg string
}

type flagDef struct {
	value interface{}
	typ   string
	names []string
}

// New creates a new interspersed flag set
func New() *FlagSet {
	return &FlagSet{
		flags: make(map[string]*flagDef),
	}
}

// StringVar registers a string flag
func (fs *FlagSet) StringVar(p *string, name string, defaultVal string, usage string) {
	*p = defaultVal
	fd := &flagDef{value: p, typ: "string"}
	// Check if there's already a def with same pointer
	for _, existing := range fs.flags {
		if existing.value == p {
			existing.names = append(existing.names, name)
			fs.flags[name] = existing
			return
		}
	}
	fd.names = []string{name}
	fs.flags[name] = fd
}

// BoolVar registers a bool flag
