// parseArgs parses args with interspersed flag support using a simple manual approach
type parsedArgs struct {
	HostFile    string
	Out         string
	Columns     []string
	NoColor     bool
	Quiet       bool
	Raw         bool
	Remaining   []string
}

func parseCommon(args []string) (*parsedArgs, error) {
	p := &parsedArgs{
		HostFile: "/etc/hosts",
		Out:      "table",
	}

	i := 0
	for i < len(args) {
		arg := args[i]

		if arg == "--" {
			p.Remaining = append(p.Remaining, args[i+1:]...)
			break
		}

		if !strings.HasPrefix(arg, "-") {
			p.Remaining = append(p.Remaining, arg)
			i++
			continue
		}

		// Handle flags
		name, value, hasValue := splitFlag(arg)

		switch name {
		case "host-file":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --host-file requires argument") }
				value = args[i]
			}
			p.HostFile = value
		case "out", "o":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --%s requires argument", name) }
				value = args[i]
			}
			p.Out = value
		case "column", "c":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --%s requires argument", name) }
				value = args[i]
			}
			for _, c := range strings.Split(value, ",") {
				p.Columns = append(p.Columns, strings.TrimSpace(c))
			}
		case "no-color":
			p.NoColor = true
			if hasValue && value == "false" {
				p.NoColor = false
			}
		case "quiet", "q":
			p.Quiet = true
			if hasValue && value == "false" {
				p.Quiet = false
			}
		case "raw":
			p.Raw = true
			if hasValue && value == "false" {
				p.Raw = false
			}
		case "help", "h":
			p.Remaining = append([]string{"--help"}, p.Remaining...)
			// Put remaining args back
			p.Remaining = append(p.Remaining, args[i+1:]...)
			return p, nil
		// Ignore unknown flags silently for now
		default:
			// Return the flag as remaining (will be handled by caller)
			p.Remaining = append(p.Remaining, arg)
		}

		i++
	}

	return p, nil
}

func splitFlag(arg string) (name, value string, hasValue bool) {
	// Strip leading dashes
	s := strings.TrimLeft(arg, "-")
	if idx := strings.Index(s, "="); idx >= 0 {
		return s[:idx], s[idx+1:], true
	}
	return s, "", false
}

