func parseEnableDisableFlags(args []string, all, only *bool, wait *time.Duration) ([]string, error) {
	var remaining []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") || arg == "--" {
			remaining = append(remaining, args[i:]...)
			break
		}
		name, value, hasValue := splitFlag(arg)
		switch name {
		case "all":
			*all = true
		case "only":
			*only = true
		case "wait", "w":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --%s requires argument", name) }
				value = args[i]
			}
			d, err := time.ParseDuration(value)
			if err != nil { return nil, err }
			*wait = d
		default:
			remaining = append(remaining, arg)
		}
		i++
	}
	return remaining, nil
}

