		return fmt.Errorf("unknown command")
	}
}

func runSyncDocker(args []string) error {
	var domain string = "loc"
	var network string
	var wait time.Duration = -1

	var remaining []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") || arg == "--" {
			remaining = append(remaining, args[i:]...)
			break
		}
		name, value, hasValue := splitFlag(arg)
		switch name {
		case "domain", "d":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --%s requires argument", name) }
				value = args[i]
			}
			domain = value
		case "network":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --network requires argument") }
				value = args[i]
			}
			network = value
		case "wait", "w":
			if !hasValue {
				i++
				if i >= len(args) { return nil, fmt.Errorf("flag --%s requires argument", name) }
				value = args[i]
			}
			d, err := time.ParseDuration(value)
			if err != nil { return nil, err }
			wait = d
		default:
			remaining = append(remaining, arg)
		}
		i++
	}

	p, err := parseCommon(remaining)
	if err != nil { return err }

	profileName := ""
	if len(p.Remaining) > 0 {
		profileName = p.Remaining[0]
	}

	return cli.CmdSyncDocker(toGlobalFlags(p), profileName, domain, network, wait)
}

