func showCommandHelp(cmd string) error {
	switch cmd {
	case "list":
		printListHelp()
	case "status":
		printStatusHelp()
	case "enable":
		printEnableHelp()
	case "disable":
		printDisableHelp()
	case "toggle":
		printToggleHelp()
	case "add":
		printAddHelp()
	case "remove", "rm":
		printRemoveHelp()
	case "replace":
		printReplaceHelp()
	case "backup":
		printBackupHelp()
	case "restore":
		printRestoreHelp()
	case "sync":
		printSyncHelp()
	default:
		printUsage()
	}
	return nil
}

